WITH exploded AS (SELECT id, plan, effective_from, EXPLODE(discounts) AS val FROM price_tiers) SELECT DATE_TRUNC('QUARTER', effective_from) AS quarter_start, ROUND(SUM(val) / NULLIF(COUNT(CASE WHEN plan = 'starter' THEN 1 END), 0), 2) AS val_per_starter, ROUND(SUM(val) / NULLIF(COUNT(CASE WHEN plan = 'starter' THEN 1 END), 0), 2) AS val_per_starter_2, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list FROM exploded GROUP BY DATE_TRUNC('QUARTER', effective_from)
